#include <bits/stdc++.h>
using namespace std;
int main(){int n,c=0;while(cin>>n){vector<long long>a(n);for(auto &v:a)cin>>v;long long best=0;for(int i=0;i<n;i++){long long p=1;for(int j=i;j<n;j++){p*=a[j];best=max(best,p);}}cout<<"Case #"<<++c<<": The maximum product is "<<best<<".\n\n";}}

